body.script:
function ixCustomerMode() {
    var radios = document.getElementsByName('customer_mode');
    var mode = 'existing';
    for (var i = 0; i != radios.length; i++) {
        if (radios[i].checked) { mode = radios[i].value; }
    }
    document.getElementById('ix-existing').style.display = (mode == 'new') ? 'none' : 'block';
    document.getElementById('ix-newcust').style.display = (mode == 'new') ? 'grid' : 'none';
}
ixCustomerMode();

function ixProductChange(sel) {
    var opt = sel.options[sel.selectedIndex];
    var row = sel.parentNode.parentNode;
    var price = row.querySelector('input[name=price]');
    if (opt.getAttribute('data-price') !== null) {
        if (!price.value || parseFloat(price.value) == 0) {
            price.value = opt.getAttribute('data-price');
        }
    }
}

function ixAddTreatmentRow() {
    var body = document.querySelector('#ix-treatments tbody');
    var last = body.rows[body.rows.length - 1];
    var copy = last.cloneNode(true);
    var inputs = copy.querySelectorAll('input');
    for (var i = 0; i != inputs.length; i++) { inputs[i].value = ''; }
    copy.querySelector('select').selectedIndex = 0;
    copy.querySelector('.ix-tno').textContent = body.rows.length + 1;
    body.appendChild(copy);
}

function ixAddProductRow() {
    var body = document.querySelector('#ix-products tbody');
    var last = body.rows[body.rows.length - 1];
    var copy = last.cloneNode(true);
    copy.querySelector('select').selectedIndex = 0;
    copy.querySelector('input[name=qty]').value = '1';
    copy.querySelector('input[name=price]').value = '0';
    body.appendChild(copy);
}

var ixCanvas = document.getElementById('ix-sig');
var ixDrawn = false;
function ixSigClear() {
    if (!ixCanvas) { return; }
    ixCanvas.getContext('2d').clearRect(0, 0, ixCanvas.width, ixCanvas.height);
    ixDrawn = false;
    document.getElementById('ix-sig-data').value = '';
}
if (ixCanvas) {
    var ctx = ixCanvas.getContext('2d');
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#111827';
    var drawing = false;
    function pos(e) {
        var r = ixCanvas.getBoundingClientRect();
        return {
            x: (e.clientX - r.left) * (ixCanvas.width / r.width),
            y: (e.clientY - r.top) * (ixCanvas.height / r.height)
        };
    }
    ixCanvas.addEventListener('pointerdown', function (e) {
        drawing = true;
        var p = pos(e);
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        e.preventDefault();
    });
    ixCanvas.addEventListener('pointermove', function (e) {
        if (!drawing) { return; }
        var p = pos(e);
        ctx.lineTo(p.x, p.y);
        ctx.stroke();
        ixDrawn = true;
        e.preventDefault();
    });
    window.addEventListener('pointerup', function () { drawing = false; });
}
document.getElementById('ix-form').addEventListener('submit', function () {
    if (ixCanvas) {
        if (ixDrawn) {
            document.getElementById('ix-sig-data').value = ixCanvas.toDataURL('image/png');
        }
    }
});
